import { Link, useLocation } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { useState } from 'react';

export default function Header() {
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems = [
    { href: '#about', label: 'About' },
    { href: '#contact', label: 'Contact' },
  ];

  const handleNavClick = (href: string) => {
    setIsMobileMenuOpen(false);
    if (href.startsWith('#')) {
      const el = document.querySelector(href);
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <header className="fixed top-0 left-0 right-0 z-50 bg-background/90 backdrop-blur-sm">
      <div className="max-w-6xl mx-auto px-6 md:px-12">
        <div className="flex h-20 items-center justify-between">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0" aria-label="Alex Rivera home">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="AR"
              className="h-8 w-auto object-contain shrink-0"
            />
          </Link>

          {/* Desktop nav */}
          <nav className="hidden md:flex items-center gap-10">
            {navItems.map((item) => (
              <button
                key={item.href}
                onClick={() => handleNavClick(item.href)}
                className="relative text-sm tracking-widest uppercase text-muted-foreground hover:text-foreground transition-colors duration-300 group"
              >
                {item.label}
                <span className="absolute -bottom-0.5 left-0 w-0 h-px bg-foreground transition-all duration-300 ease-out group-hover:w-full" />
              </button>
            ))}
          </nav>

          {/* Mobile toggle */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 text-foreground"
            aria-label="Toggle menu"
          >
            {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>

        {/* Mobile menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-border py-6">
            <nav className="flex flex-col gap-4">
              {navItems.map((item) => (
                <button
                  key={item.href}
                  onClick={() => handleNavClick(item.href)}
                  className="text-sm tracking-widest uppercase text-muted-foreground hover:text-foreground transition-colors text-left py-1"
                >
                  {item.label}
                </button>
              ))}
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

export default function Footer() {
  const currentYear = new Date().getFullYear();

  return (
    <footer className="border-t border-border bg-background">
      <div className="max-w-6xl mx-auto px-6 md:px-12 py-8">
        <div className="flex flex-col md:flex-row justify-between items-center gap-2">
          <p className="text-xs tracking-widest uppercase text-muted-foreground">
            © {currentYear} Alex Rivera
          </p>
          <p className="text-xs tracking-widest uppercase text-muted-foreground">
            Designed &amp; built by Alex Rivera
          </p>
        </div>
      </div>
    </footer>
  );
}

import { Helmet } from '@dr.pogodin/react-helmet';
import { motion } from 'motion/react';
import { Github, Linkedin, Twitter, ChevronDown, Mail } from 'lucide-react';

const fadeUp = {
  hidden: { opacity: 0, y: 28 },
  visible: (delay = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.55, delay, ease: 'easeOut' as const },
  }),
};

const techStack = ['React', 'TypeScript', 'Node.js', 'PostgreSQL', 'AWS'];

const socials = [
  { icon: Github, label: 'GitHub', href: 'https://github.com' },
  { icon: Linkedin, label: 'LinkedIn', href: 'https://linkedin.com' },
  { icon: Twitter, label: 'Twitter / X', href: 'https://twitter.com' },
];

export default function HomePage() {
  return (
    <>
      <Helmet>
        <title>Alex Rivera — Full-Stack Developer</title>
        <meta
          name="description"
          content="Alex Rivera is a full-stack developer crafting thoughtful, performant digital experiences with React, Node.js, and cloud infrastructure."
        />
      </Helmet>

      {/* ── Hero ─────────────────────────────────────────── */}
      <section className="relative min-h-screen flex flex-col justify-center pt-20">
        {/* Subtle dot texture */}
        <div
          className="pointer-events-none absolute inset-0 opacity-[0.035]"
          style={{
            backgroundImage: 'radial-gradient(circle, #0F0F0F 1px, transparent 1px)',
            backgroundSize: '28px 28px',
          }}
        />

        <div className="max-w-6xl mx-auto px-6 md:px-12 w-full">
          {/* Eyebrow */}
          <motion.p
            className="text-xs tracking-[0.25em] uppercase text-muted-foreground mb-6"
            initial="hidden"
            animate="visible"
            custom={0}
            variants={fadeUp}
          >
            Full-Stack Developer
          </motion.p>

          {/* Name — monumental */}
          <motion.h1
            className="font-heading text-[clamp(3.5rem,12vw,9rem)] leading-[0.92] tracking-tight text-foreground mb-8"
            initial="hidden"
            animate="visible"
            custom={0.12}
            variants={fadeUp}
          >
            Alex
            <br />
            Rivera
          </motion.h1>

          {/* Thin rule */}
          <motion.div
            className="w-16 h-px bg-accent mb-8"
            initial={{ scaleX: 0, originX: 0 }}
            animate={{ scaleX: 1 }}
            transition={{ duration: 0.6, delay: 0.3, ease: 'easeOut' as const }}
          />

          {/* Tagline */}
          <motion.p
            className="text-base md:text-lg font-light text-muted-foreground max-w-md leading-relaxed"
            initial="hidden"
            animate="visible"
            custom={0.28}
            variants={fadeUp}
          >
            Crafting thoughtful digital experiences — clean code, considered design, and systems that scale.
          </motion.p>
        </div>

        {/* Scroll indicator */}
        <motion.div
          className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-1 text-muted-foreground"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.9, duration: 0.6 }}
        >
          <motion.div
            animate={{ y: [0, 6, 0] }}
            transition={{ repeat: Infinity, duration: 2, ease: 'easeInOut' as const }}
          >
            <ChevronDown size={18} strokeWidth={1.5} />
          </motion.div>
        </motion.div>
      </section>

      {/* Section divider */}
      <div className="max-w-6xl mx-auto px-6 md:px-12">
        <div className="h-px bg-border" />
      </div>

      {/* ── About ────────────────────────────────────────── */}
      <section id="about" className="py-32 md:py-40">
        <div className="max-w-6xl mx-auto px-6 md:px-12">
          <div className="grid grid-cols-1 md:grid-cols-[200px_1fr] gap-12 md:gap-20">
            {/* Label column */}
            <motion.div
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              custom={0}
              variants={fadeUp}
            >
              <p className="text-xs tracking-[0.25em] uppercase text-muted-foreground pt-1">
                About
              </p>
            </motion.div>

            {/* Content column */}
            <div>
              <motion.p
                className="text-xl md:text-2xl font-light text-foreground leading-relaxed mb-10"
                initial="hidden"
                whileInView="visible"
                viewport={{ once: true }}
                custom={0.08}
                variants={fadeUp}
              >
                I'm Alex Rivera, a full-stack developer with a passion for building clean, performant web applications. I specialize in React, Node.js, and cloud infrastructure — and I care deeply about the craft of software.
              </motion.p>

              <motion.p
                className="text-base text-muted-foreground leading-relaxed mb-12"
                initial="hidden"
                whileInView="visible"
                viewport={{ once: true }}
                custom={0.16}
                variants={fadeUp}
              >
                With over five years of experience across startups and scale-ups, I bring both technical depth and product sensibility to every project. I believe great software is invisible — it just works, beautifully.
              </motion.p>

              {/* Tech pills */}
              <motion.div
                className="flex flex-wrap gap-3"
                initial="hidden"
                whileInView="visible"
                viewport={{ once: true }}
                custom={0.24}
                variants={fadeUp}
              >
                {techStack.map((tech) => (
                  <span
                    key={tech}
                    className="text-xs tracking-widest uppercase border border-border text-muted-foreground px-4 py-2 rounded-full"
                  >
                    {tech}
                  </span>
                ))}
              </motion.div>
            </div>
          </div>
        </div>
      </section>

      {/* Section divider */}
      <div className="max-w-6xl mx-auto px-6 md:px-12">
        <div className="h-px bg-border" />
      </div>

      {/* ── Contact ──────────────────────────────────────── */}
      <section id="contact" className="py-32 md:py-40">
        <div className="max-w-6xl mx-auto px-6 md:px-12">
          <div className="grid grid-cols-1 md:grid-cols-[200px_1fr] gap-12 md:gap-20">
            {/* Label column */}
            <motion.div
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              custom={0}
              variants={fadeUp}
            >
              <p className="text-xs tracking-[0.25em] uppercase text-muted-foreground pt-1">
                Get in Touch
              </p>
            </motion.div>

            {/* Content column */}
            <div>
              <motion.h2
                className="font-heading text-4xl md:text-5xl text-foreground leading-tight mb-10"
                initial="hidden"
                whileInView="visible"
                viewport={{ once: true }}
                custom={0.08}
                variants={fadeUp}
              >
                Let's build something together.
              </motion.h2>

              {/* Email */}
              <motion.div
                className="mb-12"
                initial="hidden"
                whileInView="visible"
                viewport={{ once: true }}
                custom={0.16}
                variants={fadeUp}
              >
                <a
                  href="mailto:alex@alexrivera.dev"
                  className="group inline-flex items-center gap-3 text-lg md:text-xl text-foreground relative"
                >
                  <Mail size={18} strokeWidth={1.5} className="text-muted-foreground shrink-0" />
                  <span className="relative">
                    alex@alexrivera.dev
                    <span className="absolute -bottom-0.5 left-0 w-0 h-px bg-foreground transition-all duration-400 ease-out group-hover:w-full" />
                  </span>
                </a>
              </motion.div>

              {/* Social icons */}
              <motion.div
                className="flex items-center gap-8"
                initial="hidden"
                whileInView="visible"
                viewport={{ once: true }}
                custom={0.24}
                variants={fadeUp}
              >
                {socials.map(({ icon: Icon, label, href }) => (
                  <a
                    key={label}
                    href={href}
                    target="_blank"
                    rel="noopener noreferrer"
                    aria-label={label}
                    className="group flex items-center gap-2 text-muted-foreground hover:text-foreground transition-colors duration-300"
                  >
                    <Icon size={20} strokeWidth={1.5} />
                    <span className="text-xs tracking-widest uppercase hidden sm:inline relative">
                      {label}
                      <span className="absolute -bottom-0.5 left-0 w-0 h-px bg-foreground transition-all duration-300 ease-out group-hover:w-full" />
                    </span>
                  </a>
                ))}
              </motion.div>
            </div>
          </div>
        </div>
      </section>
    </>
  );
}
